mapper.select:
select c.*
from (SELECT a.id, a.sha256_code_list, a.local_id, a.api_code,
             ROW_NUMBER() OVER (PARTITION BY a.sha256_code_list ORDER BY a.id) AS row_num
      from b_xiecheng_cps_colliding_data_front a
      where a.is_deleted = 0
        and a.local_id = #{localId}
        and a.push_status = 1
        and a.status = 1) as c
where c.row_num = 1

    and c.id > #{minId}

order by c.id
limit #{pageSize}

